protected void init()
{
    api = XAPI_APIS::CreateContractPart;
    super();
}

protected void postRun()
{
    EGS_API_DataContract_Response res;

    if (!responseText)
    {
        return;
    }

    res      = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseText);
    logKey   = "ContractPartNum";
    logValue = res.parmMessage();
}

protected str body()
{
    EXU_UtilityInstallation uinst;
    Map                     configMap;
    EXU_ContractNum         conNum;
    str                     instNum;

    configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>', curExt());

    var accNum = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount');

    CustTable custTable = CustTable::find(accNum);

    configMap.insert('<AlternativeCustomerNumber>', custTable.EXU_AlternativeCustomerNumber);
    configMap.insert('<custAccount>', accNum);

    conNum = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateContract, 'ContractNum');
    configMap.insert('<Contract>', conNum);

    instNum = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateInstallation, 'InstNum');
    configMap.insert('<InstallationNum>', instNum);

    select firstonly uinst
        where uinst.InstNum == instNum;
    configMap.insert('<deliveryCategory>', uinst.DeliveryCategory);

    EXU_ContractPartTable partTable;
    select firstonly partTable
        where partTable.ContractNum == conNum;
    configMap.insert('<productNum>', partTable.ProductNum);

    str dateStr = date2Str(partTable.Startdate, 
                            321, 
                            DateDay::Digits2, 
                            DateSeparator::Hyphen, 
                            DateMonth::Digits2, 
                            DateSeparator::Hyphen, 
                            DateYear::Digits4); // Todo: move it to util
    configMap.insert('<startdate>', dateStr);

    return this.prepareBody(configMap);
}
